select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"native_identity_key":"nlscale:20261102:ol:OL719942W"},"seq":1,"relation":"works","after_row":{"id":987154001,"title":"De zaterdagvliegers","cover_id":null,"author_id":969300006,"work_type":"collection","source_type":"open_library","open_library_id":"OL719942W","first_publish_year":1981,"native_identity_key":"nlscale:20261102:ol:OL719942W"},"before_row":null},{"key":{"open_library_edition_id":"OL3870103M"},"seq":2,"relation":"editions","after_row":{"id":987254001,"title":"De zaterdagvliegers","isbn_10":null,"isbn_13":"9789029518284","work_id":987154001,"cover_id":null,"language":"dut","publisher":"De Arbeiderspers","publish_date":null,"open_library_edition_id":"OL3870103M"},"before_row":null},{"key":{"work_id":987154001,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"Maarten ’t Hart brengt verhalen samen over jeugdherinneringen, zijn werk als bioloog, het schrijverschap en zijn tijd voor de klas. Kleine gebeurtenissen krijgen betekenis door nauwkeurige aandacht voor mensen, dieren en de omgeving. In het titelverhaal kijkt een verteller terug op buurtbewoners en de verschillen tussen duivenliefhebbers die op zaterdag of op zondag vliegen. De bundel verkent hoe waarnemen vertrouwde overtuigingen kan veranderen. De afzonderlijke verhalen vormen geen doorlopende roman, maar tonen verschillende kanten van een persoonlijke leefwereld.","work_id":987154001,"evidence":[{"note":"Genuine separate 1981 collection by Maarten ''t Hart; reuse actual original-content review content-amendment-015.json. Independently bound Dutch hardcoverISBN 9789029518284; exclude alternate paperback/e-book ISBNs, no Work merge or invented author. Format independently confirmed at https://www.deslegte.com/rotterdam/de-zaterdagvliegers-343438/","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p810871424"],"reference":"new-work-dossier-readings-055.js