ps://data.bibliotheken.nl/id/nbt/p810871424","review_batch":"nl-scale-20261102-055","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":969300006},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL15243650W"},"seq":5,"relation":"works","after_row":{"id":987154002,"title":"Uit talloos veel miljoenen","cover_id":null,"author_id":969300005,"work_type":"novel","source_type":"open_library","open_library_id":"OL15243650W","first_publish_year":1981,"native_identity_key":"nlscale:20261102:ol:OL15243650W"},"before_row":null},{"key":{"open_library_edition_id":"OL3846343M"},"seq":6,"relation":"editions","after_row":{"id":987254002,"title":"Uit talloos veel miljoenen","isbn_10":null,"isbn_13":"9789023460770","work_id":987154002,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL3846343M"},"before_row":null},{"key":{"work_id":987154002,"language":"nl"},"seq":7,"relation":"catalog_work_descriptions","after_row":{"text":"Clemens en Sita van Wessel hopen ieder op een ander leven. Hij wil aan de universiteit hogerop komen, maar ziet een jongere collega benoemd worden op de plek die hij zichzelf had toegedacht. Zij probeert haar ambities waar te maken door een kinderboek te schrijven. Binnen hun huwelijk versterken die teleurstellingen elkaar. Hermans volgt hoe verlangens naar erkenning botsen met de dagelijkse werkelijkheid en met de verschillende milieus waaruit de twee afkomstig zijn.","work_id":987154002,"evidence":[{"note":"Genuine separate 1981 novel by Willem Frederik Hermans; reuse actual original-content review content-amendment-021.json. Independently bound Dutch hardcoverISBN 9789023460770; exclude alternate paperback/e-book ISBNs, no Work merge or invented author. Format independently confirmed at https://www.boekwinkeltjes.nl/b/225245334/Uit-talloos-veel-miljoenen-druk-1/","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.