ed","bound_language":"dut","card_cover_url":null,"bound_author_id":969300005},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL15249098W"},"seq":9,"relation":"works","after_row":{"id":987154003,"title":"Klaas kwam niet","cover_id":null,"author_id":969300005,"work_type":"collection","source_type":"open_library","open_library_id":"OL15249098W","first_publish_year":1983,"native_identity_key":"nlscale:20261102:ol:OL15249098W"},"before_row":null},{"key":{"open_library_edition_id":"OL2809271M"},"seq":10,"relation":"editions","after_row":{"id":987254003,"title":"Klaas kwam niet","isbn_10":null,"isbn_13":"9789023460831","work_id":987154003,"cover_id":null,"language":"dut","publisher":"De Bezige Bij","publish_date":null,"open_library_edition_id":"OL2809271M"},"before_row":null},{"key":{"work_id":987154003,"language":"nl"},"seq":11,"relation":"catalog_work_descriptions","after_row":{"text":"Hermans verzamelt in deze bundel essays en polemische stukken over schrijvers, filosofen, kunst en politiek. Franse literatuur, de behandeling van vertalingen en de reputatie van bekende auteurs keren in verschillende bijdragen terug. Ook de denkbeelden van Karl Popper worden kritisch onderzocht. De teksten vormen geen doorlopend betoog, maar laten zien hoe Hermans uiteenlopende onderwerpen vanuit zijn eigen lezerservaring en overtuigingen benadert. Daarbij wisselen uitvoeriger beschouwingen en kortere reacties op gebeurtenissen en publicaties elkaar af.","work_id":987154003,"evidence":[{"note":"Genuine separate 1983 collection by Willem Frederik Hermans; reuse actual original-content review content-amendment-021.json. Independently bound Dutch hardcoverISBN 9789023460831; exclude alternate paperback/e-book ISBNs, no Work merge or invented author. Format independently confirmed at https://www.deslegte.com/boeken/willem-frederik-hermans/eerste-druk/","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p832266922"],"reference":"n